//! Native DiceBear avatar generation.
//!
//! DiceBear (dicebear.com) is a JavaScript library; upstream this fork
//! pre-rendered a fixed set of avatars because of that. This module generates
//! them natively instead — any `(style, seed)` renders a real DiceBear avatar
//! with no JavaScript and no network, exactly the "generative like JS" feature.
//!
//! It is a two-part port:
//!   - **the engine** (here): the seeded PRNG from `@dicebear/core` plus the
//!     component selection and SVG assembly, reproduced in Rust;
//!   - **the data** (`dicebear_data.json`, regenerated by
//!     `script/generate-avatar-data.mjs`): each style's component SVG parts,
//!     variant/probability/colour schema, and body layout, extracted from the
//!     real `@dicebear/collection` packages. The parts are reused as data; only
//!     the generation code is ported.
//!
//! Output need not be byte-identical to the JS library — any deterministic pick
//! yields a valid avatar of that style — so the prng-consumption order is our
//! own (colours, then components) rather than JS's.
//!
//! Attribution (a licence condition for the CC BY styles) lives on the About
//! page; see `avatar_picker::AVATAR_ATTRIBUTION`.

use std::collections::HashMap;
use std::sync::{Arc, LazyLock};

use bytes::Bytes;
use serde::Deserialize;
use warpui::assets::asset_cache::{AssetSource, AsyncAssetId, AsyncAssetType};

// ---------------------------------------------------------------------------
// Data model (matches dicebear_data.json)
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct Bundle {
    styles: Vec<StyleInfo>,
    data: HashMap<String, StyleData>,
}

/// A selectable style: stable id (`"bottts"`) + display label (`"Robots"`).
#[derive(Deserialize, Clone)]
pub struct StyleInfo {
    pub id: String,
    pub label: String,
}

#[derive(Deserialize)]
struct StyleData {
    #[serde(rename = "viewBox")]
    view_box: String,
    groups: Vec<Group>,
    colors: Vec<ColorGroup>,
    /// Background palette, present only for styles whose official default
    /// render paints one (fun-emoji, thumbs, shapes). One entry is picked per
    /// avatar and drawn as a full-viewBox rect behind the body.
    #[serde(default)]
    background: Option<Vec<String>>,
    /// Body template with `{{group:NAME}}` markers; `None` should not happen for
    /// a well-formed style.
    layout: Option<String>,
}

#[derive(Deserialize)]
struct Group {
    name: String,
    variants: Vec<String>,
    /// `None` = always shown; `Some(p)` = shown with probability `p` percent.
    probability: Option<i32>,
    /// variant name -> SVG template (with `{{color:X}}` / `{{component:X}}`
    /// placeholders).
    templates: HashMap<String, String>,
}

#[derive(Deserialize)]
struct ColorGroup {
    name: String,
    values: Vec<String>,
}

static BUNDLE: LazyLock<Bundle> = LazyLock::new(|| {
    serde_json::from_str(include_str!("dicebear_data.json"))
        .expect("bundled dicebear_data.json is valid")
});

/// Every style, in picker order. The first is the default (`bottts` / Robots).
pub fn styles() -> &'static [StyleInfo] {
    &BUNDLE.styles
}

/// The default style id for a fresh install.
pub const DEFAULT_STYLE: &str = "bottts";

/// The display label for a style id, if known.
pub fn label(style_id: &str) -> Option<&'static str> {
    BUNDLE
        .styles
        .iter()
        .find(|s| s.id == style_id)
        .map(|s| s.label.as_str())
}

// ---------------------------------------------------------------------------
// PRNG — faithful port of @dicebear/core/lib/utils/prng.js
// ---------------------------------------------------------------------------

fn xorshift(mut value: i32) -> i32 {
    value ^= value.wrapping_shl(13);
    value ^= value >> 17; // JS `>>` is an arithmetic (sign-preserving) shift
    value ^= value.wrapping_shl(5);
    value
}

struct Prng {
    value: i32,
}

impl Prng {
    fn new(seed: &str) -> Self {
        // seed.slice(0, 1024) on UTF-16 code units, matching JS.
        let mut hash: i32 = 0;
        for unit in seed.encode_utf16().take(1024) {
            hash = hash
                .wrapping_shl(5)
                .wrapping_sub(hash)
                .wrapping_add(unit as i32);
            hash = xorshift(hash);
        }
        Prng {
            value: if hash == 0 { 1 } else { hash },
        }
    }

    fn next(&mut self) -> i32 {
        self.value = xorshift(self.value);
        self.value
    }

    fn integer(&mut self, min: i32, max: i32) -> i32 {
        const MIN: f64 = -2_147_483_648.0;
        const MAX: f64 = 2_147_483_647.0;
        let n = self.next() as f64;
        (((n - MIN) / (MAX - MIN)) * ((max + 1 - min) as f64) + (min as f64)).floor() as i32
    }

    fn bool(&mut self, likelihood: i32) -> bool {
        self.integer(1, 100) <= likelihood
    }

    /// Picks an element; `None` for an empty slice (still consuming one step, as
    /// JS does).
    fn pick<'a>(&mut self, arr: &'a [String]) -> Option<&'a str> {
        if arr.is_empty() {
            self.next();
            None
        } else {
            let i = self.integer(0, arr.len() as i32 - 1) as usize;
            arr.get(i).map(String::as_str)
        }
    }
}

/// `@dicebear/core`'s convertColor: a bare hex becomes `#hex`; `transparent`
/// stays.
fn convert_color(color: &str) -> String {
    if color == "transparent" {
        color.to_owned()
    } else {
        format!("#{color}")
    }
}

// ---------------------------------------------------------------------------
// Generation
// ---------------------------------------------------------------------------

/// Generates the SVG for `(style_id, seed)`, or `None` for an unknown style.
/// Deterministic: the same pair always renders the same SVG.
pub fn generate(style_id: &str, seed: &str) -> Option<String> {
    let data = BUNDLE.data.get(style_id)?;
    let mut prng = Prng::new(seed);

    // 0. Background, for the styles that ship one: picked first, drawn first.
    let background = data
        .background
        .as_ref()
        .and_then(|values| prng.pick(values))
        .map(|color| {
            let color = convert_color(color);
            // Every DiceBear viewBox is "0 0 W H".
            let mut parts = data.view_box.split_whitespace().skip(2);
            let w = parts.next().unwrap_or("100");
            let h = parts.next().unwrap_or("100");
            format!("<rect fill=\"{color}\" width=\"{w}\" height=\"{h}\"/>")
        })
        .unwrap_or_default();

    // 1. Colours (one pick per group, in data order).
    let mut colors: HashMap<&str, String> = HashMap::new();
    for group in &data.colors {
        let picked = prng
            .pick(&group.values)
            .map(convert_color)
            .unwrap_or_else(|| "transparent".to_owned());
        colors.insert(group.name.as_str(), picked);
    }

    // 2. Components (pick a variant per group, then apply its probability).
    let mut picked: HashMap<&str, Option<&str>> = HashMap::new();
    for group in &data.groups {
        let variant = prng.pick(&group.variants);
        let shown = match group.probability {
            Some(p) => prng.bool(p),
            None => true,
        };
        picked.insert(group.name.as_str(), if shown { variant } else { None });
    }

    // 3. Assemble the body from the layout, then wrap in the root <svg>.
    let layout = data.layout.as_deref().unwrap_or("");
    let body = substitute(layout, data, &picked, &colors, 0);
    Some(format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"{}\" fill=\"none\">{background}{body}</svg>",
        data.view_box
    ))
}

/// Substitutes `{{group:G}}`, `{{component:G}}`, `{{color:C}}`, and
/// `{{compname:G}}` markers in `s`. Component markers render the picked variant
/// of that group (recursively; depth-guarded against pathological data).
fn substitute(
    s: &str,
    data: &StyleData,
    picked: &HashMap<&str, Option<&str>>,
    colors: &HashMap<&str, String>,
    depth: usize,
) -> String {
    if depth > 16 {
        return String::new();
    }
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(start) = rest.find("{{") {
        out.push_str(&rest[..start]);
        let after = &rest[start + 2..];
        let Some(end) = after.find("}}") else {
            out.push_str("{{");
            rest = after;
            continue;
        };
        let marker = &after[..end];
        rest = &after[end + 2..];

        if let Some(group) = marker
            .strip_prefix("group:")
            .or_else(|| marker.strip_prefix("component:"))
        {
            out.push_str(&render_group(group, data, picked, colors, depth));
        } else if let Some(color) = marker.strip_prefix("color:") {
            out.push_str(colors.get(color).map(String::as_str).unwrap_or("transparent"));
        } else if let Some(group) = marker.strip_prefix("compname:") {
            out.push_str(picked.get(group).and_then(|v| *v).unwrap_or(""));
        }
        // Unknown markers are dropped.
    }
    out.push_str(rest);
    out
}

fn render_group(
    group: &str,
    data: &StyleData,
    picked: &HashMap<&str, Option<&str>>,
    colors: &HashMap<&str, String>,
    depth: usize,
) -> String {
    let Some(Some(variant)) = picked.get(group) else {
        return String::new();
    };
    let Some(g) = data.groups.iter().find(|g| g.name == group) else {
        return String::new();
    };
    let Some(template) = g.templates.get(*variant) else {
        return String::new();
    };
    substitute(template, data, picked, colors, depth + 1)
}

// ---------------------------------------------------------------------------
// AssetSource integration
// ---------------------------------------------------------------------------

/// Namespace marker for generated-avatar cache ids.
struct DiceBearAvatar;
impl AsyncAssetType for DiceBearAvatar {}

/// An [`AssetSource`] that renders the avatar for `(style_id, seed)` on demand
/// and caches it by id, so an `Image` can display a generated avatar the same
/// way it displays any other asset.
///
/// An unknown style id (e.g. one saved before that style was culled from the
/// bundle) falls back to [`DEFAULT_STYLE`] instead of an empty tile.
pub fn avatar_source(style_id: &str, seed: &str) -> AssetSource {
    let style = if BUNDLE.data.contains_key(style_id) {
        style_id.to_owned()
    } else {
        DEFAULT_STYLE.to_owned()
    };
    let seed = seed.to_owned();
    AssetSource::Async {
        id: AsyncAssetId::new::<DiceBearAvatar>(format!("{style}:{seed}")),
        fetch: Arc::new(move || {
            let style = style.clone();
            let seed = seed.clone();
            Box::pin(async move {
                let svg = generate(&style, &seed)
                    .ok_or_else(|| anyhow::anyhow!("unknown avatar style {style}"))?;
                Ok(Bytes::from(svg.into_bytes()))
            })
        }),
    }
}

